1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #14161c;
16	    color: #e8e8ec;
17	    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
18	  }
19	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
20	  .board {
21	    display: grid;
22	    grid-template-columns: repeat(10, 28px);
23	    grid-template-rows: repeat(20, 28px);
24	    gap: 1px;
25	    padding: 1px;
26	    background: #2a2d36;
27	    border: 2px solid #3a3e4a;
28	  }
29	  .cell { width: 28px; height: 28px; background: #0d0e12; }
30	  .side { display: flex; flex-direction: column; gap: 16px; min-width: 140px; }
31	  .panel { background: #1d2028; border: 1px solid #2f333d; padding: 10px 12px; }
32	  .label { font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em; color: #8a8f9c; }
33	  .value { font-size: 22px; font-weight: 600; margin-top: 2px; }
34	  .preview {
35	    display: grid;
36	    grid-template-columns: repeat(4, 16px);
37	    grid-template-rows: repeat(2, 16px);
38	    gap: 1px;
39	    margin-top: 8px;
40	  }
41	  .preview .mini { width: 16px; height: 16px; background: transparent; }
42	  .status { font-size: 14px; color: #ff8a8a; min-height: 18px; }
43	  button {
44	    font: inherit;
45	    background: #2f333d;
46	    color: #e8e8ec;
47	    border: 1px solid #454a57;
48	    padding: 6px 10px;
49	    cursor: pointer;
50	  }
51	  button:hover { background: #3a3e4a; }
52	  .help { font-size: 12px; color: #8a8f9c; line-height: 1.6; }
53	
54	  /* Piece colours, shared by the board and the preview. */
55	  [data-piece="I"] { background: #22c5e6 !important; }
56	  [data-piece="O"] { background: #f2d024 !important; }
57	  [data-piece="T"] { background: #a64ee6 !important; }
58	  [data-piece="S"] { background: #3fcf5a !important; }
59	  [data-piece="Z"] { background: #e8423f !important; }
60	  [data-piece="J"] { background: #3563e9 !important; }
61	  [data-piece="L"] { background: #f08a24 !important; }
62	</style>
63	</head>
64	<body>
65	<div class="game">
66	  <div class="board" data-testid="board" id="board"></div>
67	  <div class="side">
68	    <div class="panel"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
69	    <div class="panel"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
70	    <div class="panel"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
71	    <div class="panel"><div class="label">Next</div><div class="preview" id="preview"></div></div>
72	    <div class="status" id="status"></div>
73	    <button type="button" id="restart">New game</button>
74	    <div class="help">← → move<br>↑ rotate<br>↓ soft drop<br>Space hard drop</div>
75	  </div>
76	</div>
77	<script>
78	(function () {
79	  "use strict";
80	
81	  var ROWS = 20;
82	  var COLS = 10;
83	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
84	  var MIN_UPCOMING = 5;
85	
86	  // Spawn shapes as [row, col] offsets from the top-left of the spawn box.
87	  var SHAPES = {
88	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
89	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
90	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
91	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
92	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
93	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
94	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
95	  };
96	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
97	  // Size of the square box each piece rotates inside.
98	  var BOX = { I: 4, O: 2, T: 3, S: 3, Z: 3, J: 3, L: 3 };
99	  // Sideways shifts tried, in order, when a rotated shape does not fit in place.
100	  var KICKS = [0, -1, 1, -2, 2];
101	  // Locking rule (decision): 2 ticks unable to fall, left/right restarts it at most 3 times.
102	  var LOCK_TICKS = 2;
103	  var MAX_LOCK_RESETS = 3;
104	  var LINE_SCORES = [0, 100, 300, 500, 800];
105	
106	  // board[row][col] is a piece letter or null. The renderer and getBoard both read it.
107	  var board;
108	  var current;   // { type, cells, row, col, lockTicks, lockResets } or null
109	  var upcoming;  // array of piece letters, soonest first
110	  var score, level, lines, status;
111	  var timer = null;
112	
113	  var boardEl = document.getElementById("board");
114	  var previewEl = document.getElementById("preview");
115	  var scoreEl = document.getElementById("score");
116	  var levelEl = document.getElementById("level");
117	  var linesEl = document.getElementById("lines");
118	  var statusEl = document.getElementById("status");
119	  var cellEls = [];
120	  var previewEls = [];
121	
122	  // [REQ-001] Build the 200 board cells and the preview cells once.
123	  function buildDom() {
124	    for (var r = 0; r < ROWS; r++) {
125	      cellEls.push([]);
126	      for (var c = 0; c < COLS; c++) {
127	        var el = document.createElement("div");
128	        el.className = "cell";
129	        el.setAttribute("data-testid", "cell");
130	        el.setAttribute("data-row", String(r));
131	        el.setAttribute("data-col", String(c));
132	        el.setAttribute("data-filled", "false");
133	        el.setAttribute("data-piece", "");
134	        boardEl.appendChild(el);
135	        cellEls[r].push(el);
136	      }
137	    }
138	    for (var i = 0; i < 8; i++) {
139	      var m = document.createElement("div");
140	      m.className = "mini";
141	      m.setAttribute("data-piece", "");
142	      previewEl.appendChild(m);
143	      previewEls.push(m);
144	    }
145	  }
146	
147	  function emptyBoard() {
148	    var b = [];
149	    for (var r = 0; r < ROWS; r++) {
150	      var row = [];
151	      for (var c = 0; c < COLS; c++) row.push(null);
152	      b.push(row);
153	    }
154	    return b;
155	  }
156	
157	  function isType(t) { return TYPES.indexOf(t) !== -1; }
158	
159	  // [REQ-001] Random generator: a shuffled bag of all seven pieces.
160	  function randomBag() {
161	    var bag = TYPES.slice();
162	    for (var i = bag.length - 1; i > 0; i--) {
163	      var j = Math.floor(Math.random() * (i + 1));
164	      var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
165	    }
166	    return bag;
167	  }
168	
169	  function fillUpcoming() {
170	    while (upcoming.length < MIN_UPCOMING) upcoming = upcoming.concat(randomBag());
171	  }
172	
173	  function cellsOf(piece, row, col) {
174	    return piece.cells.map(function (o) { return [row + o[0], col + o[1]]; });
175	  }
176	
177	  function fits(piece, row, col) {
178	    var cells = cellsOf(piece, row, col);
179	    for (var i = 0; i < cells.length; i++) {
180	      var r = cells[i][0], c = cells[i][1];
181	      if (r < 0 || r >= ROWS || c < 0 || c >= COLS) return false;
182	      if (board[r][c]) return false;
183	    }
184	    return true;
185	  }
186	
187	  // [REQ-001] Take the next piece from the queue and place it at the top.
188	  function spawn() {
189	    fillUpcoming();
190	    var type = upcoming.shift();
191	    fillUpcoming();
192	    var piece = {
193	      type: type,
194	      cells: SHAPES[type].map(function (o) { return o.slice(); }),
195	      row: 0,
196	      col: SPAWN_COL[type],
197	      lockTicks: 0,
198	      lockResets: 0
199	    };
200	    if (!fits(piece, piece.row, piece.col)) {
201	      current = null;
202	      status = "over";
203	      stopTimer();
204	      return;
205	    }
206	    current = piece;
207	  }
208	
209	  function clearLines() {
210	    var kept = board.filter(function (row) {
211	      return row.some(function (v) { return !v; });
212	    });
213	    var cleared = ROWS - kept.length;
214	    while (kept.length < ROWS) {
215	      var empty = [];
216	      for (var c = 0; c < COLS; c++) empty.push(null);
217	      kept.unshift(empty);
218	    }
219	    board = kept;
220	    if (cleared > 0) {
221	      score += LINE_SCORES[cleared] * level;
222	      lines += cleared;
223	      var newLevel = Math.floor(lines / 10) + 1;
224	      if (newLevel !== level) {
225	        level = newLevel;
226	        if (status === "running") startTimer();
227	      }
228	    }
229	  }
230	
231	  // [REQ-001] Lock the falling piece into the board, clear lines, spawn the next piece.
232	  function lockPiece() {
233	    cellsOf(current, current.row, current.col).forEach(function (rc) {
234	      board[rc[0]][rc[1]] = current.type;
235	    });
236	    current = null;
237	    clearLines();
238	    spawn();
239	  }
240	
241	  // [REQ-001] One gravity step. The real timer and __tetris.tick both call this.
242	  // [REQ-002] A step that cannot move the piece down counts one tick of lock delay.
243	  function gravityStep() {
244	    if (status !== "running" || !current) return;
245	    if (fits(current, current.row + 1, current.col)) {
246	      current.row += 1;
247	      current.lockTicks = 0;
248	    } else {
249	      current.lockTicks += 1;
250	      if (current.lockTicks >= LOCK_TICKS) lockPiece();
251	    }
252	  }
253	
254	  // [REQ-002] Sideways move. While resting, a move restarts the lock delay, at most 3 times per piece.
255	  function shift(dx) {
256	    if (!fits(current, current.row, current.col + dx)) return;
257	    var resting = !fits(current, current.row + 1, current.col);
258	    current.col += dx;
259	    if (resting && current.lockResets < MAX_LOCK_RESETS) {
260	      current.lockResets += 1;
261	      current.lockTicks = 0;
262	    }
263	  }
264	
265	  // [REQ-002] Rotate clockwise inside the piece's box; try sideways shifts; refuse if none fit.
266	  function rotateCW() {
267	    var n = BOX[current.type];
268	    var rotated = { type: current.type, cells: current.cells.map(function (o) { return [o[1], n - 1 - o[0]]; }) };
269	    for (var i = 0; i < KICKS.length; i++) {
270	      if (fits(rotated, current.row, current.col + KICKS[i])) {
271	        current.cells = rotated.cells;
272	        current.col += KICKS[i];
273	        return;
274	      }
275	    }
276	  }
277	
278	  // [REQ-001] Player actions: left, right, softDrop, hardDrop. [REQ-002] rotateCW.
279	  function doInput(action) {
280	    if (status !== "running" || !current) return;
281	    if (action === "left") {
282	      shift(-1);
283	    } else if (action === "right") {
284	      shift(1);
285	    } else if (action === "rotateCW") {
286	      rotateCW();
287	    } else if (action === "softDrop") {
288	      if (fits(current, current.row + 1, current.col)) current.row += 1;
289	    } else if (action === "hardDrop") {
290	      while (fits(current, current.row + 1, current.col)) current.row += 1;
291	      lockPiece();
292	    }
293	  }
294	
295	  function gravityInterval() {
296	    return Math.max(100, 1000 - (level - 1) * 90);
297	  }
298	
299	  function stopTimer() {
300	    if (timer !== null) { clearInterval(timer); timer = null; }
301	  }
302	
303	  function startTimer() {
304	    stopTimer();
305	    timer = setInterval(function () {
306	      gravityStep();
307	      render();
308	    }, gravityInterval());
309	  }
310	
311	  // [REQ-001] Draw the whole game state into the DOM, synchronously.
312	  function render() {
313	    var drawn = board.map(function (row) { return row.slice(); });
314	    if (current) {
315	      cellsOf(current, current.row, current.col).forEach(function (rc) {
316	        drawn[rc[0]][rc[1]] = current.type;
317	      });
318	    }
319	    for (var r = 0; r < ROWS; r++) {
320	      for (var c = 0; c < COLS; c++) {
321	        var v = drawn[r][c] || "";
322	        var el = cellEls[r][c];
323	        if (el.getAttribute("data-piece") !== v) {
324	          el.setAttribute("data-piece", v);
325	          el.setAttribute("data-filled", v ? "true" : "false");
326	        }
327	      }
328	    }
329	    previewEls.forEach(function (m) { m.setAttribute("data-piece", ""); });
330	    var nextType = upcoming[0];
331	    if (nextType) {
332	      SHAPES[nextType].forEach(function (o) {
333	        previewEls[o[0] * 4 + o[1]].setAttribute("data-piece", nextType);
334	      });
335	    }
336	    scoreEl.textContent = String(score);
337	    levelEl.textContent = String(level);
338	    linesEl.textContent = String(lines);
339	    statusEl.textContent = status === "over" ? "Game over" : "";
340	  }
341	
342	  // [REQ-001] Start a fresh game, optionally from a fixed piece queue.
343	  function newGame(queue) {
344	    board = emptyBoard();
345	    score = 0;
346	    level = 1;
347	    lines = 0;
348	    status = "running";
349	    upcoming = Array.isArray(queue) ? queue.filter(isType) : [];
350	    current = null;
351	    spawn();
352	    if (status === "running") startTimer();
353	    render();
354	  }
355	
356	  window.__tetris = {
357	    newGame: function (queue) { newGame(queue); },
358	
359	    setQueue: function (queue) {
360	      upcoming = Array.isArray(queue) ? queue.filter(isType) : [];
361	      fillUpcoming();
362	      render();
363	    },
364	
365	    setBoard: function (rows) {
366	      var b = emptyBoard();
367	      for (var r = 0; r < ROWS; r++) {
368	        var line = (rows && rows[r]) || "";
369	        for (var c = 0; c < COLS; c++) {
370	          var ch = line.charAt(c);
371	          b[r][c] = isType(ch) ? ch : null;
372	        }
373	      }
374	      board = b;
375	      render();
376	    },
377	
378	    tick: function (n) {
379	      if (n === undefined) n = 1;
380	      for (var i = 0; i < n; i++) gravityStep();
381	      if (status === "running") startTimer();
382	      render();
383	    },
384	
385	    input: function (action) {
386	      doInput(action);
387	      render();
388	    },
389	
390	    getBoard: function () {
391	      return board.map(function (row) {
392	        return row.map(function (v) { return v || "."; }).join("");
393	      });
394	    },
395	
396	    getState: function () {
397	      return {
398	        current: current
399	          ? { type: current.type, cells: cellsOf(current, current.row, current.col) }
400	          : null,
401	        next: upcoming.slice(),
402	        score: score,
403	        level: level,
404	        lines: lines,
405	        status: status
406	      };
407	    }
408	  };
409	
410	  var KEYS = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", " ": "hardDrop" };
411	
412	  document.addEventListener("keydown", function (e) {
413	    var action = KEYS[e.key];
414	    if (!action) return;
415	    e.preventDefault();
416	    window.__tetris.input(action);
417	  });
418	
419	  document.getElementById("restart").addEventListener("click", function (e) {
420	    e.currentTarget.blur();
421	    newGame();
422	  });
423	
424	  buildDom();
425	  newGame();
426	})();
427	</script>
428	</body>
429	</html>
